 public partial class MainForm : Form
 {
  public void ShowCommunities(){Page("Communities");content.Controls.Add(PageBanner("Groups","Communities","Join focused spaces, meet people and keep conversations organized.",205));content.Controls.Add(Section("Your communities",35,335));var create=Btn("+ New community",content.ClientSize.Width-205,325,165);create.Anchor=AnchorStyles.Top|AnchorStyles.Right;create.Click+=(s,e)=>{var name=Prompt("Community name","Create Community");if(string.IsNullOrWhiteSpace(name))return;var desc=Prompt("Short description","Create Community")??"";db.Data.Communities.Add(new Community{Id=Guid.NewGuid().ToString(),Name=name.Trim(),Description=desc.Trim(),OwnerUserId=Session.CurrentUser.Id,CreatedAt=DateTime.Now,MemberUserIds=new System.Collections.Generic.List<string>{Session.CurrentUser.Id}});LogActivity("Created community "+name.Trim());db.Save();ShowCommunities();};content.Controls.Add(create);int y=335;foreach(var g in db.Data.Communities.OrderByDescending(x=>x.CreatedAt)){var c=Card(y,138);var icon=new ModernPanel{Location=new Point(15,15),Size=new Size(54,54),BackColor=ThemeColors.SurfaceHover,BorderRadius=14,BorderColor=ThemeColors.BorderColor,BorderSize=1};icon.Controls.Add(new Label{Text="◎",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,ForeColor=ThemeColors.Primary,Font=new Font("Segoe UI",18,FontStyle.Bold)});c.Controls.Add(icon);c.Controls.Add(Txt(g.Name,82,12,390,25));c.Controls.Add(Txt(g.Description,82,40,460,38));c.Controls.Add(new Label{Text=g.MemberUserIds.Count+" members",Location=new Point(82,88),AutoSize=true,ForeColor=ThemeColors.TextMuted});var joined=g.MemberUserIds.Contains(Session.CurrentUser.Id);var b=Btn(joined?"Leave":"Join",c.Width-125,25,90);b.Anchor=AnchorStyles.Top|AnchorStyles.Right;b.Click+=(ss,ee)=>{if(joined)g.MemberUserIds.Remove(Session.CurrentUser.Id);else g.MemberUserIds.Add(Session.CurrentUser.Id);db.Save();ShowCommunities();};c.Controls.Add(b);content.Controls.Add(c);y+=152;}}
  public void ShowEvents(){Page("Events");content.Controls.Add(PageBanner("Calendar","Events","Plan meetups, launches and community sessions with a clear messenger-style agenda.",205));content.Controls.Add(Section("Upcoming events",35,335));var add=Btn("+ New event",content.ClientSize.Width-180,325,140);add.Anchor=AnchorStyles.Top|AnchorStyles.Right;add.Click+=(s,e)=>{var title=Prompt("Event title","Create Event");if(string.IsNullOrWhiteSpace(title))return;var place=Prompt("Location / online link","Create Event")??"Online";db.Data.Events.Add(new SocialEvent{Id=Guid.NewGuid().ToString(),Title=title.Trim(),Description="Community event",OwnerUserId=Session.CurrentUser.Id,StartsAt=DateTime.Now.AddDays(7),Location=place.Trim(),AttendeeUserIds=new System.Collections.Generic.List<string>{Session.CurrentUser.Id}});LogActivity("Created event "+title.Trim());db.Save();ShowEvents();};content.Controls.Add(add);int y=335;foreach(var ev in db.Data.Events.OrderBy(x=>x.StartsAt)){var c=Card(y,110);c.Controls.Add(Txt(ev.Title,15,12,460,25));c.Controls.Add(Txt(ev.StartsAt.ToString("MMM d, yyyy · HH:mm")+"  ·  "+ev.Location,15,43,600,25));c.Controls.Add(new Label{Text=ev.AttendeeUserIds.Count+" attending",Location=new Point(15,76),AutoSize=true,ForeColor=ThemeColors.TextMuted});var going=ev.AttendeeUserIds.Contains(Session.CurrentUser.Id);var b=Btn(going?"Going ✓":"RSVP",c.Width-125,25,90);b.Anchor=AnchorStyles.Top|AnchorStyles.Right;b.Click+=(ss,ee)=>{if(going)ev.AttendeeUserIds.Remove(Session.CurrentUser.Id);else ev.AttendeeUserIds.Add(Session.CurrentUser.Id);db.Save();ShowEvents();};c.Controls.Add(b);content.Controls.Add(c);y+=123;}}
  public void ShowPolls(){Page("Polls");content.Controls.Add(PageBanner("Voice","Polls","Ask your network, compare responses and make community decisions visible.",158));content.Controls.Add(Section("Community polls",35,292));content.Controls.Add(Txt("Ask your community and collect lightweight feedback.",35,95,700));var add=Btn("Create Poll",35,135,130);add.Click+=(s,e)=>{var q=Prompt("Question","Create Poll");if(string.IsNullOrWhiteSpace(q))return;var a=Prompt("Option 1","Create Poll");var b=Prompt("Option 2","Create Poll");if(string.IsNullOrWhiteSpace(a)||string.IsNullOrWhiteSpace(b))return;db.Data.Polls.Add(new Poll{Id=Guid.NewGuid().ToString(),UserId=Session.CurrentUser.Id,Question=q.Trim(),CreatedAt=DateTime.Now,Options=new System.Collections.Generic.List<PollOption>{new PollOption{Text=a.Trim()},new PollOption{Text=b.Trim()}}});LogActivity("Created a poll");db.Save();ShowPolls();};content.Controls.Add(add);int y=290;foreach(var poll in db.Data.Polls.OrderByDescending(x=>x.CreatedAt)){var c=Card(y,155);c.Controls.Add(Txt(poll.Question,15,12,600,28));int ox=15;foreach(var o in poll.Options){var votes=o.VoterUserIds.Count;var b=Btn(o.Text+" · "+votes,ox,58,180);b.Click+=(ss,ee)=>{foreach(var z in poll.Options)z.VoterUserIds.Remove(Session.CurrentUser.Id);o.VoterUserIds.Add(Session.CurrentUser.Id);db.Save();ShowPolls();};c.Controls.Add(b);ox+=195;}c.Controls.Add(new Label{Text=poll.Options.Sum(x=>x.VoterUserIds.Count)+" total votes",Location=new Point(15,112),AutoSize=true,ForeColor=ThemeColors.TextMuted});content.Controls.Add(c);y+=168;}}
  public void ShowCollections(){Page("Collections");var cols=db.Data.Collections.Where(x=>x.UserId==Session.CurrentUser.Id).OrderByDescending(x=>x.CreatedAt).ToList();content.Controls.Add(PageBanner("Library","Collections","Organize saved posts into focused sets for research, inspiration and later reading.",158));content.Controls.Add(StatCard("Collections",cols.Count.ToString(),35,292,180));content.Controls.Add(StatCard("Saved posts",db.Data.Posts.Count(x=>x.SavedBy.Contains(Session.CurrentUser.Id)).ToString(),230,292,180));var add=Btn("+ New collection",content.ClientSize.Width-205,302,165);add.Anchor=AnchorStyles.Top|AnchorStyles.Right;add.Click+=(ss,ee)=>{var n=Prompt("Collection name","New Collection");if(string.IsNullOrWhiteSpace(n))return;db.Data.Collections.Add(new PostCollection{Id=Guid.NewGuid().ToString(),UserId=Session.CurrentUser.Id,Name=n.Trim(),CreatedAt=DateTime.Now});LogActivity("Created collection "+n.Trim());db.Save();ShowCollections();};content.Controls.Add(add);int y=420;if(cols.Count==0){content.Controls.Add(EmptyState("◇","No collections yet","Create a collection to organize saved posts into your own library.",y));return;}foreach(var col in cols){var c=Card(y,112);var icon=new ModernPanel{Location=new Point(16,18),Size=new Size(56,56),BackColor=ThemeColors.SurfaceHover,BorderRadius=24,BorderColor=ThemeColors.BorderColor,BorderSize=1};icon.Controls.Add(new Label{Text="◇",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,ForeColor=ThemeColors.Primary,Font=new Font("Segoe UI",16,FontStyle.Bold)});c.Controls.Add(icon);c.Controls.Add(new Label{Text=col.Name,Location=new Point(90,20),AutoSize=true,ForeColor=ThemeColors.TextPrimary,Font=new Font("Segoe UI Semibold",11,FontStyle.Bold)});c.Controls.Add(new Label{Text=col.PostIds.Count+" posts  ·  Created "+col.CreatedAt.ToString("MMM d"),Location=new Point(90,52),AutoSize=true,ForeColor=ThemeColors.TextMuted});var fill=Btn("Add saved",c.Width-145,28,110);fill.Anchor=AnchorStyles.Top|AnchorStyles.Right;fill.Click+=(ss,ee)=>{foreach(var post in db.Data.Posts.Where(x=>x.SavedBy.Contains(Session.CurrentUser.Id)))if(!col.PostIds.Contains(post.Id))col.PostIds.Add(post.Id);db.Save();ShowCollections();};c.Controls.Add(fill);content.Controls.Add(c);y+=126;}}
 }
